    41	int main(int argc, char *argv[])
    42	{
    43	  int ret;
    44	
    45	  if (argc > 1 && strcmp(argv[1], "audio") == 0)
    46	    {
    47	      return velawear_audio_hw_test();
    48	    }
    49	
    50	  syslog(LOG_INFO, "[VelaWear] Agent starting...\n");
    51	  syslog(LOG_INFO, "[VelaWear] Agent starting...\n");
    52	
    53	  /* Initialize agent structure */
    54	
    55	  memset(&g_agent, 0, sizeof(velawear_agent_t));
    56	  g_agent.running = false;
    57	  g_agent.power_mode = VELAWEAR_POWER_IDLE;
    58	
    59	  /* Set up signal handler */
    60	
    61	  signal(SIGTERM, velawear_signal_handler);
    62	  signal(SIGINT, velawear_signal_handler);
    63	
    64	  /* Initialize subsystems */
    65	
    66	  ret = velawear_init(&g_agent);
    67	  if (ret < 0)
    68	    {
    69	      syslog(LOG_ERR, "[VelaWear] Initialization failed: %d\n", ret);
    70	      return EXIT_FAILURE;
    71	    }
    72	
    73	  /* Start the agent */
    74	
    75	  ret = velawear_start(&g_agent);
    76	  if (ret < 0)
    77	    {
    78	      syslog(LOG_ERR, "[VelaWear] Start failed: %d\n", ret);
    79	      velawear_cleanup(&g_agent);
    80	      return EXIT_FAILURE;
    81	    }
    82	
    83	  syslog(LOG_INFO, "[VelaWear] Agent started successfully\n");
    84	
    85	  /* Main loop: sample the board IMU and feed the event pipeline. */
    86	
    87	  bool fall_reported = false;
    88	  while (g_agent.running)
    89	    {
    90	      int period_us = 20000;
    91	
    92	      if (g_agent.imu.initialized)
    93	        {
    94	          imu_data_t sample;
    95	          motion_state_t motion;
    96	          velawear_event_t event;
    97	          int sample_ret;
    98	
    99	          sample_ret = imu_sensor_read(&g_agent.imu, &sample);
   100	          if (sample_ret == VELAWEAR_OK)
   101	            {
   102	              memset(&event, 0, sizeof(event));
   103	              event.type = VELAWEAR_EVENT_IMU_DATA;
   104	              event.priority = VELAWEAR_PRIORITY_NORMAL;
   105	              event.timestamp = sample.timestamp;
   106	              event.data.imu.x = sample.accel_x;
   107	              event.data.imu.y = sample.accel_y;
   108	              event.data.imu.z = sample.accel_z;
   109	              event_manager_push(&g_agent.events, &event);
   110	
   111	              motion = imu_sensor_get_motion_state(&g_agent.imu);
   112	              if (motion.fall_detected && !fall_reported)
   113	                {
   114	                  event.type = VELAWEAR_EVENT_FALL;
   115	                  event.priority = VELAWEAR_PRIORITY_CRITICAL;
   116	                  event_manager_push(&g_agent.events, &event);
   117	                  fall_reported = true;
   118	                }
   119	              else if (!motion.fall_detected)
   120	                {
   121	                  fall_reported = false;
   122	                }
   123	            }
   124	
   125	          if (g_agent.config.imu_sample_rate_hz > 0)
   126	            {
   127	              period_us = 1000000 / g_agent.config.imu_sample_rate_hz;
   128	              if (period_us < 1000)
   129	                {
   130	                  period_us = 1000;
   131	                }
   132	            }
   133	        }
   134	
   135	      /* LVGL initialization and timer handling stay on this task. */
   136	
   137	      display_manager_tick(&g_agent.display);
   138	      usleep(period_us);
   139	    }
   140	
   141	  /* Cleanup */
   142	
   143	  velawear_cleanup(&g_agent);
   144	  syslog(LOG_INFO, "[VelaWear] Agent stopped\n");
   145	
   146	  return EXIT_SUCCESS;
   147	}
