   226	      /* Non-fatal: continue without audio */
   227	    }
   228	
   229	  /* Initialize LLM client */
   230	
   231	  ret = velawear_llm_init(&agent->llm);
   232	  if (ret < 0)
   233	    {
   234	      syslog(LOG_WARNING, "[VelaWear] LLM init failed: %d\n", ret);
   235	      /* Non-fatal: continue without LLM */
   236	    }
   237	
   238	  ret = event_manager_register_handler(&agent->events,
   239	                                       VELAWEAR_EVENT_NONE,
   240	                                       velawear_event_handler,
   241	                                       agent,
   242	                                       VELAWEAR_PRIORITY_NORMAL);
   243	  if (ret < 0)
   244	    {
   245	      syslog(LOG_ERR, "[VelaWear] Event handler registration failed: %d\n",
   246	             ret);
   247	      return ret;
   248	    }
   249	
   250	  ret = action_manager_register_handler(&agent->actions,
   251	                                        VELAWEAR_ACTION_LOG,
   252	                                        velawear_log_action_handler,
   253	                                        agent);
   254	  if (ret < 0)
   255	    {
   256	      syslog(LOG_ERR, "[VelaWear] Action handler registration failed: %d\n",
   257	             ret);
   258	      return ret;
   259	    }
   260	
   261	  return OK;
   262	}
