   264	static int velawear_start(velawear_agent_t *agent)
   265	{
   266	  int ret;
   267	
   268	  /* Start event manager thread */
   269	
   270	  ret = event_manager_start(&agent->events);
   271	  if (ret < 0)
   272	    {
   273	      syslog(LOG_ERR, "[VelaWear] Event manager start failed: %d\n", ret);
