   281	    {
   282	      syslog(LOG_ERR, "[VelaWear] Action manager start failed: %d\n", ret);
   283	      return ret;
   284	    }
   285	
   286	  /* Decision rules are evaluated synchronously for each event. */
   287	
   288	  /* Mark agent as running */
   289	
   290	  agent->running = true;
   291	
   292	  return OK;
   293	}
