   295	static void velawear_cleanup(velawear_agent_t *agent)
   296	{
   297	  /* Stop subsystems in reverse order */
   298	
   299	  agent->running = false;
   300	
   301	  velawear_llm_cleanup(&agent->llm);
   302	  audio_sensor_cleanup(&agent->audio);
   303	  imu_sensor_cleanup(&agent->imu);
   304	  action_manager_cleanup(&agent->actions);
   305	  event_manager_cleanup(&agent->events);
