   318	static int velawear_event_handler(velawear_event_t *event, void *context)
   319	{
   320	  velawear_agent_t *agent = (velawear_agent_t *)context;
   321	  velawear_state_t state;
   322	
   323	  if (event->type == VELAWEAR_EVENT_IMU_DATA)
