   325	      motion_state_t motion = imu_sensor_get_motion_state(&agent->imu);
   326	      state_manager_update_motion(&agent->state_mgr,
   327	                                  motion.is_moving,
   328	                                  motion.is_running);
   329	    }
   330	
   331	  state = state_manager_get_state(&agent->state_mgr);
   332	  agent->state = state;
   333	  decision_engine_evaluate(&agent->engine, &state, event);
   334	  return VELAWEAR_OK;
   335	}
