     1	/*
     2	 * VelaWear Agent - Event Manager Implementation
     3	 *
     4	 * Manages all events from sensors, BLE, touch, and system.
     5	 *
     6	 * Author: pjjuihj
     7	 * Team: 329 - dela
     8	 */
     9	
    10	#include <nuttx/config.h>
    11	#include <stdio.h>
    12	#include <stdlib.h>
    13	#include <string.h>
    14	#include <errno.h>
    15	#include <syslog.h>
    16	#include <pthread.h>
    17	#include <mqueue.h>
    18	#include <fcntl.h>
    19	#include <unistd.h>
    20	
    21	#include "velawear.h"
    22	#include "event_manager.h"
    23	
    24	/****************************************************************************
    25	 * Private Functions
    26	 ****************************************************************************/
    27	
    28	static void *event_manager_thread(void *arg)
    29	{
    30	  velawear_events_t *events = (velawear_events_t *)arg;
    31	  velawear_event_t event;
    32	  int ret;
    33	
    34	  syslog(LOG_INFO, "[EventMgr] Thread started\n");
    35	
    36	  while (events->running)
    37	    {
    38	      /* Pop event from queue with timeout */
    39	
    40	      ret = event_manager_pop(events, &event, 1000);
    41	      if (ret < 0)
    42	        {
    43	          /* Timeout or error, continue */
    44	
    45	          continue;
    46	        }
    47	
    48	      /* Dispatch event to registered handlers */
    49	
    50	      pthread_mutex_lock(&events->lock);
    51	
    52	      for (int i = 0; i < events->handler_count; i++)
    53	        {
    54	          if (events->handlers[i].event_type == event.type ||
    55	              events->handlers[i].event_type == VELAWEAR_EVENT_NONE)
    56	            {
    57	              ret = events->handlers[i].handler(&event,
    58	                                                events->handlers[i].context);
    59	              if (ret < 0)
    60	                {
    61	                  syslog(LOG_WARNING,
    62	                         "[EventMgr] Handler %d returned error: %d\n",
    63	                         i, ret);
    64	                }
    65	            }
    66	        }
    67	
    68	      pthread_mutex_unlock(&events->lock);
    69	    }
    70	
    71	  syslog(LOG_INFO, "[EventMgr] Thread stopped\n");
    72	  return NULL;
    73	}
    74	
    75	/****************************************************************************
    76	 * Public Functions
    77	 ****************************************************************************/
    78	
    79	int event_manager_init(velawear_events_t *events)
    80	{
    81	  struct mq_attr attr;
    82	
    83	  memset(events, 0, sizeof(velawear_events_t));
    84	
    85	  /* Initialize mutex */
    86	
    87	  pthread_mutex_init(&events->lock, NULL);
    88	
    89	  /* Create message queue */
    90	
    91	  attr.mq_flags = 0;
    92	  attr.mq_maxmsg = EVENT_QUEUE_SIZE;
    93	  /* Keep the mqueue payload within CONFIG_MQ_MAXMSGSIZE.  Events are
    94	   * copied through heap-backed pointers so the full event union can
    95	   * remain available to handlers. */
    96	  attr.mq_msgsize = sizeof(uintptr_t);
    97	  attr.mq_curmsgs = 0;
    98	
    99	  /* A crashed instance may leave pointer messages behind.  Remove the
   100	   * old queue before creating a fresh one for this process. */
   101	  mq_unlink("/velawear_events");
   102	
   103	  events->queue = mq_open("/velawear_events", O_CREAT | O_RDWR, 0644,
   104	                          &attr);
   105	  if (events->queue == (mqd_t)-1)
   106	    {
   107	      syslog(LOG_ERR, "[EventMgr] Failed to create message queue: %d\n",
   108	             errno);
   109	      return VELAWEAR_ERR_IO;
   110	    }
   111	
   112	  events->running = false;
   113	  events->handler_count = 0;
   114	
   115	  syslog(LOG_INFO, "[EventMgr] Initialized\n");
   116	  return VELAWEAR_OK;
   117	}
   118	
   119	int event_manager_start(velawear_events_t *events)
   120	{
   121	  int ret;
   122	
   123	  if (events->running)
   124	    {
   125	      return VELAWEAR_ERR_BUSY;
   126	    }
   127	
   128	  events->running = true;
   129	
   130	  ret = pthread_create(&events->thread, NULL, event_manager_thread, events);
   131	  if (ret != 0)
   132	    {
   133	      syslog(LOG_ERR, "[EventMgr] Failed to create thread: %d\n", ret);
   134	      events->running = false;
   135	      return VELAWEAR_ERR_IO;
   136	    }
   137	
   138	  syslog(LOG_INFO, "[EventMgr] Started\n");
   139	  return VELAWEAR_OK;
   140	}
   141	
   142	void event_manager_cleanup(velawear_events_t *events)
   143	{
   144	  if (events->running)
   145	    {
   146	      events->running = false;
   147	      pthread_join(events->thread, NULL);
   148	    }
   149	
   150	  if (events->queue != (mqd_t)-1)
   151	    {
   152	      mq_close(events->queue);
   153	      mq_unlink("/velawear_events");
   154	    }
   155	
   156	  pthread_mutex_destroy(&events->lock);
   157	
   158	  syslog(LOG_INFO, "[EventMgr] Cleaned up\n");
   159	}
   160	
   161	int event_manager_push(velawear_events_t *events, velawear_event_t *event)
   162	{
   163	  velawear_event_t *copy;
   164	  uintptr_t message;
   165	  int ret;
   166	
   167	  if (events->queue == (mqd_t)-1 || event == NULL)
   168	    {
   169	      return VELAWEAR_ERR_IO;
   170	    }
   171	
   172	  copy = (velawear_event_t *)malloc(sizeof(*copy));
   173	  if (copy == NULL)
   174	    {
   175	      return VELAWEAR_ERR_NOMEM;
   176	    }
   177	
   178	  memcpy(copy, event, sizeof(*copy));
   179	  message = (uintptr_t)copy;
   180	  ret = mq_send(events->queue, (const char *)&message,
   181	                sizeof(message), event->priority);
   182	  if (ret < 0)
   183	    {
   184	      free(copy);
   185	      syslog(LOG_WARNING, "[EventMgr] Failed to push event: %d\n", errno);
   186	      return VELAWEAR_ERR_IO;
   187	    }
   188	
   189	  return VELAWEAR_OK;
   190	}
   191	
   192	int event_manager_pop(velawear_events_t *events, velawear_event_t *event,
   193	                      int timeout_ms)
   194	{
   195	  struct timespec timeout;
   196	  uintptr_t message;
   197	  ssize_t nbytes;
   198	
   199	  if (events->queue == (mqd_t)-1 || event == NULL)
   200	    {
   201	      return VELAWEAR_ERR_IO;
   202	    }
   203	
   204	  /* Calculate timeout */
   205	
   206	  clock_gettime(CLOCK_REALTIME, &timeout);
   207	  timeout.tv_sec += timeout_ms / 1000;
   208	  timeout.tv_nsec += (timeout_ms % 1000) * 1000000;
   209	  if (timeout.tv_nsec >= 1000000000)
   210	    {
   211	      timeout.tv_sec++;
   212	      timeout.tv_nsec -= 1000000000;
   213	    }
   214	
   215	  nbytes = mq_timedreceive(events->queue, (char *)&message,
   216	                           sizeof(message), NULL, &timeout);
   217	  if (nbytes < 0)
   218	    {
   219	      if (errno == ETIMEDOUT)
   220	        {
   221	          return VELAWEAR_ERR_TIMEOUT;
   222	        }
   223	
   224	      return VELAWEAR_ERR_IO;
   225	    }
   226	
   227	  if (nbytes != sizeof(message) || message == 0)
   228	    {
   229	      return VELAWEAR_ERR_IO;
   230	    }
   231	
   232	  memcpy(event, (const void *)message, sizeof(*event));
   233	  free((void *)message);
   234	  return VELAWEAR_OK;
   235	}
   236	
   237	int event_manager_register_handler(velawear_events_t *events,
   238	                                   uint32_t event_type,
   239	                                   event_handler_t handler,
   240	                                   void *context,
   241	                                   int priority)
   242	{
   243	  pthread_mutex_lock(&events->lock);
   244	
   245	  if (events->handler_count >= EVENT_HANDLER_MAX)
   246	    {
   247	      pthread_mutex_unlock(&events->lock);
   248	      return VELAWEAR_ERR_NOMEM;
   249	    }
   250	
   251	  events->handlers[events->handler_count].event_type = event_type;
   252	  events->handlers[events->handler_count].handler = handler;
   253	  events->handlers[events->handler_count].context = context;
   254	  events->handlers[events->handler_count].priority = priority;
   255	  events->handler_count++;
   256	
   257	  pthread_mutex_unlock(&events->lock);
   258	
   259	  syslog(LOG_INFO, "[EventMgr] Registered handler for type %lu\n",
   260	         (unsigned long)event_type);
   261	  return VELAWEAR_OK;
   262	}
