    80	/****************************************************************************
    81	 * Private Functions
    82	 ****************************************************************************/
    83	
    84	static void *decision_engine_thread(void *arg)
    85	{
    86	  velawear_engine_t *engine = (velawear_engine_t *)arg;
    87	  velawear_state_t state;
    88	  velawear_event_t event;
    89	  int ret;
    90	
    91	  syslog(LOG_INFO, "[Decision] Thread started\n");
    92	
    93	  while (engine->running)
    94	    {
    95	      /* Sleep for decision interval */
    96	
    97	      usleep(100000);  /* 100ms */
    98	
    99	      /* Get current state */
   100	
   101	      /* The event-driven path supplies real state and events.  Keep this
   102	       * worker safe for callers that explicitly start it by using neutral
   103	       * values instead of uninitialized stack data. */
   104	      memset(&state, 0, sizeof(state));
   105	      memset(&event, 0, sizeof(event));
   106	      state.battery_level = 100;
   107	      state.heart_rate = 60.0f;
   108	      state.is_charging = true;
   109	
   110	      /* TODO: Get state from state manager */
   111	
   112	      /* Evaluate rules by priority */
   113	
   114	      pthread_mutex_lock(&engine->lock);
   115	
   116	      for (int i = 0; i < engine->rule_count; i++)
   117	        {
   118	          if (!engine->rules[i].enabled)
   119	            {
   120	              continue;
   121	            }
   122	
   123	          if (engine->rules[i].condition &&
   124	              engine->rules[i].condition(&state, &event))
   125	            {
   126	              ret = engine->rules[i].action(&state,
   127	                                            engine->rules[i].context);
   128	              if (ret < 0)
   129	                {
   130	                  syslog(LOG_WARNING,
   131	                         "[Decision] Rule '%s' action failed: %d\n",
   132	                         engine->rules[i].name, ret);
   133	                }
   134	
   135	              /* For emergency rules, stop after first match */
   136	
   137	              if (engine->rules[i].layer == 0)
   138	                {
   139	                  break;
   140	                }
   141	            }
   142	        }
   143	
   144	      pthread_mutex_unlock(&engine->lock);
   145	    }
   146	
   147	  syslog(LOG_INFO, "[Decision] Thread stopped\n");
   148	  return NULL;
   149	}
