   160	  engine->config = config;
   161	  engine->running = false;
   162	
   163	  /* Register hardcoded emergency rules */
   164	
   165	  decision_engine_add_rule(engine, "fall_detected", 0,
   166	                           VELAWEAR_PRIORITY_CRITICAL,
   167	                           fall_detected_condition,
   168	                           fall_detected_action, NULL);
   169	
   170	  decision_engine_add_rule(engine, "heart_rate_critical", 0,
   171	                           VELAWEAR_PRIORITY_CRITICAL,
   172	                           heart_rate_critical_condition,
   173	                           heart_rate_critical_action, NULL);
   174	
   175	  decision_engine_add_rule(engine, "battery_critical", 0,
   176	                           VELAWEAR_PRIORITY_HIGH,
   177	                           battery_critical_condition,
