   185	int decision_engine_start(velawear_engine_t *engine)
   186	{
   187	  int ret;
   188	
   189	  if (engine->running)
   190	    {
   191	      return VELAWEAR_ERR_BUSY;
   192	    }
   193	
   194	  engine->running = true;
   195	
   196	  ret = pthread_create(&engine->thread, NULL, decision_engine_thread, engine);
   197	  if (ret != 0)
   198	    {
   199	      syslog(LOG_ERR, "[Decision] Failed to create thread: %d\n", ret);
   200	      engine->running = false;
   201	      return VELAWEAR_ERR_IO;
   202	    }
   203	
   204	  syslog(LOG_INFO, "[Decision] Started\n");
   205	  return VELAWEAR_OK;
   206	}
