   208	void decision_engine_cleanup(velawear_engine_t *engine)
   209	{
   210	  if (engine->running)
   211	    {
   212	      engine->running = false;
   213	      pthread_join(engine->thread, NULL);
   214	    }
   215	
   216	  pthread_mutex_destroy(&engine->lock);
   217	
   218	  syslog(LOG_INFO, "[Decision] Cleaned up\n");
