   221	int decision_engine_add_rule(velawear_engine_t *engine,
   222	                             const char *name,
   223	                             int layer,
   224	                             uint32_t priority,
   225	                             rule_condition_t condition,
   226	                             rule_action_t action,
   227	                             void *context)
   228	{
   229	  pthread_mutex_lock(&engine->lock);
   230	
   231	  if (engine->rule_count >= DECISION_RULES_MAX)
   232	    {
   233	      pthread_mutex_unlock(&engine->lock);
   234	      return VELAWEAR_ERR_NOMEM;
   235	    }
   236	
   237	  decision_rule_t *rule = &engine->rules[engine->rule_count];
   238	  rule->id = engine->rule_count;
   239	  strncpy(rule->name, name, sizeof(rule->name) - 1);
   240	  rule->layer = layer;
   241	  rule->priority = priority;
   242	  rule->condition = condition;
   243	  rule->action = action;
   244	  rule->context = context;
   245	  rule->enabled = true;
   246	
   247	  engine->rule_count++;
   248	
   249	  pthread_mutex_unlock(&engine->lock);
   250	
   251	  syslog(LOG_INFO, "[Decision] Added rule '%s' (layer=%d, priority=%lu)\n",
   252	         name, layer, (unsigned long)priority);
   253	  return rule->id;
   254	}
