   256	int decision_engine_remove_rule(velawear_engine_t *engine, int rule_id)
   257	{
   258	  pthread_mutex_lock(&engine->lock);
   259	
   260	  if (rule_id < 0 || rule_id >= engine->rule_count)
   261	    {
   262	      pthread_mutex_unlock(&engine->lock);
   263	      return VELAWEAR_ERR_INVAL;
   264	    }
   265	
   266	  engine->rules[rule_id].enabled = false;
   267	
   268	  pthread_mutex_unlock(&engine->lock);
   269	
   270	  syslog(LOG_INFO, "[Decision] Disabled rule %d\n", rule_id);
   271	  return VELAWEAR_OK;
   272	}
   273	
   274	int decision_engine_evaluate(velawear_engine_t *engine,
   275	                             velawear_state_t *state,
   276	                             velawear_event_t *event)
   277	{
   278	  int ret;
   279	
   280	  pthread_mutex_lock(&engine->lock);
   281	
   282	  for (int i = 0; i < engine->rule_count; i++)
   283	    {
   284	      if (!engine->rules[i].enabled)
   285	        {
   286	          continue;
   287	        }
   288	
   289	      if (engine->rules[i].condition &&
   290	          engine->rules[i].condition(state, event))
   291	        {
   292	          ret = engine->rules[i].action(state, engine->rules[i].context);
   293	          if (ret < 0)
   294	            {
   295	              syslog(LOG_WARNING,
   296	                     "[Decision] Rule '%s' action failed: %d\n",
   297	                     engine->rules[i].name, ret);
   298	            }
   299	
   300	          /* For emergency rules, stop after first match */
   301	
   302	          if (engine->rules[i].layer == 0)
   303	            {
   304	              pthread_mutex_unlock(&engine->lock);
   305	              return engine->rules[i].id;
   306	            }
   307	        }
   308	    }
   309	
   310	  pthread_mutex_unlock(&engine->lock);
   311	
   312	  return -1;  /* No rule matched */
   313	}
