     8	 */
     9	
    10	#include <nuttx/config.h>
    11	#include <stdio.h>
    12	#include <stdlib.h>
    13	#include <string.h>
    14	#include <errno.h>
    15	#include <syslog.h>
    16	#include <pthread.h>
    17	#include <unistd.h>
    18	
    19	#include "velawear.h"
    20	#include "action_manager.h"
    21	
    22	/****************************************************************************
    23	 * Private Functions
    24	 ****************************************************************************/
    25	
    26	static void *action_manager_thread(void *arg)
    27	{
    28	  velawear_actions_t *actions = (velawear_actions_t *)arg;
    29	  velawear_action_t action;
    30	  int ret;
    31	
    32	  syslog(LOG_INFO, "[ActionMgr] Thread started\n");
    33	
    34	  while (actions->running)
    35	    {
    36	      /* Wait for action in queue */
    37	
    38	      pthread_mutex_lock(&actions->lock);
    39	
    40	      while (actions->queue_count == 0 && actions->running)
    41	        {
    42	          pthread_cond_wait(&actions->cond, &actions->lock);
    43	        }
    44	
    45	      if (!actions->running)
    46	        {
    47	          pthread_mutex_unlock(&actions->lock);
    48	          break;
    49	        }
    50	
    51	      /* Dequeue action */
    52	
    53	      memcpy(&action, &actions->queue[actions->queue_head],
    54	             sizeof(velawear_action_t));
    55	      actions->queue_head =
    56	        (actions->queue_head + 1) % ACTION_QUEUE_SIZE;
    57	      actions->queue_count--;
    58	
    59	      pthread_mutex_unlock(&actions->lock);
    60	
    61	      /* Dispatch action to handler */
    62	
    63	      for (int i = 0; i < actions->handler_count; i++)
    64	        {
    65	          if (actions->handlers[i].action_type == action.type)
    66	            {
    67	              ret = actions->handlers[i].handler(&action,
    68	                                                 actions->handlers[i].context);
    69	              if (ret < 0)
    70	                {
    71	                  syslog(LOG_WARNING,
    72	                         "[ActionMgr] Handler for type %d failed: %d\n",
    73	                         action.type, ret);
    74	                }
    75	              break;
    76	            }
    77	        }
    78	    }
    79	
    80	  syslog(LOG_INFO, "[ActionMgr] Thread stopped\n");
    81	  return NULL;
    82	}
    83	
    84	/****************************************************************************
    85	 * Public Functions
    86	 ****************************************************************************/
    87	
    88	int action_manager_init(velawear_actions_t *actions)
    89	{
    90	  memset(actions, 0, sizeof(velawear_actions_t));
    91	
    92	  pthread_mutex_init(&actions->lock, NULL);
    93	  pthread_cond_init(&actions->cond, NULL);
    94	
    95	  actions->running = false;
    96	  actions->queue_head = 0;
    97	  actions->queue_tail = 0;
    98	  actions->queue_count = 0;
    99	
   100	  syslog(LOG_INFO, "[ActionMgr] Initialized\n");
   101	  return VELAWEAR_OK;
   102	}
   103	
   104	int action_manager_start(velawear_actions_t *actions)
   105	{
   106	  int ret;
   107	
   108	  if (actions->running)
   109	    {
   110	      return VELAWEAR_ERR_BUSY;
   111	    }
   112	
   113	  actions->running = true;
   114	
   115	  ret = pthread_create(&actions->thread, NULL, action_manager_thread, actions);
   116	  if (ret != 0)
   117	    {
   118	      syslog(LOG_ERR, "[ActionMgr] Failed to create thread: %d\n", ret);
   119	      actions->running = false;
   120	      return VELAWEAR_ERR_IO;
   121	    }
   122	
   123	  syslog(LOG_INFO, "[ActionMgr] Started\n");
   124	  return VELAWEAR_OK;
   125	}
   126	
   127	void action_manager_cleanup(velawear_actions_t *actions)
   128	{
   129	  if (actions->running)
   130	    {
   131	      actions->running = false;
   132	      pthread_cond_signal(&actions->cond);
   133	      pthread_join(actions->thread, NULL);
   134	    }
   135	
   136	  pthread_mutex_destroy(&actions->lock);
   137	  pthread_cond_destroy(&actions->cond);
   138	
   139	  syslog(LOG_INFO, "[ActionMgr] Cleaned up\n");
   140	}
   141	
   142	int action_manager_execute(velawear_actions_t *actions,
   143	                           velawear_action_t *action)
   144	{
   145	  pthread_mutex_lock(&actions->lock);
   146	
   147	  if (actions->queue_count >= ACTION_QUEUE_SIZE)
   148	    {
   149	      pthread_mutex_unlock(&actions->lock);
   150	      syslog(LOG_WARNING, "[ActionMgr] Queue full, dropping action\n");
   151	      return VELAWEAR_ERR_BUSY;
   152	    }
   153	
   154	  /* Enqueue action */
   155	
   156	  memcpy(&actions->queue[actions->queue_tail], action,
   157	         sizeof(velawear_action_t));
   158	  actions->queue_tail =
   159	    (actions->queue_tail + 1) % ACTION_QUEUE_SIZE;
   160	  actions->queue_count++;
   161	
   162	  pthread_cond_signal(&actions->cond);
   163	  pthread_mutex_unlock(&actions->lock);
   164	
   165	  return VELAWEAR_OK;
   166	}
   167	
   168	int action_manager_register_handler(velawear_actions_t *actions,
   169	                                    int action_type,
   170	                                    action_handler_t handler,
   171	                                    void *context)
   172	{
   173	  pthread_mutex_lock(&actions->lock);
   174	
   175	  if (actions->handler_count >= ACTION_HANDLERS_MAX)
   176	    {
   177	      pthread_mutex_unlock(&actions->lock);
   178	      return VELAWEAR_ERR_NOMEM;
   179	    }
   180	
   181	  actions->handlers[actions->handler_count].action_type = action_type;
   182	  actions->handlers[actions->handler_count].handler = handler;
   183	  actions->handlers[actions->handler_count].context = context;
   184	  actions->handler_count++;
   185	
   186	  pthread_mutex_unlock(&actions->lock);
   187	
   188	  syslog(LOG_INFO, "[ActionMgr] Registered handler for type %d\n",
   189	         action_type);
   190	  return VELAWEAR_OK;
   191	}
